import { MarkdownIt, StateBlock, StateCore, StateInline } from "markdown-it";
/**
 * Removes the common leading whitespace from each line.
 *
 * Blank and whitespace-only lines are ignored when computing the common indent; a tab counts as one
 * indentation character.
 *
 * 移除每行共同的前导空白。
 *
 * 计算公共缩进时会忽略空行与纯空白行；制表符按一个缩进字符计算。
 *
 * @param text - The text to dedent / 要移除缩进的文本
 * @returns The dedented text / 移除缩进后的文本
 */
export declare const dedent: (text: string) => string;
/**
 * Escapes HTML special characters (`& < > " '`).
 *
 * 转义 HTML 特殊字符（`& < > " '`）。
 *
 * @example
 *   escapeHtml('<a href="x">'); // '&lt;a href=&quot;x&quot;&gt;'
 *
 * @param unsafeHTML - The HTML content to escape / 要转义的 HTML 内容
 * @returns The escaped HTML content / 转义后的 HTML 内容
 */
export declare const escapeHtml: (unsafeHTML: string) => string;
/**
 * Escapes special characters in a string so it can be used as a literal in `new RegExp`.
 *
 * 转义字符串中的正则特殊字符，使其可作为 `new RegExp` 的字面量使用。
 *
 * @example
 *   escapeRegExp("[test]"); // String.raw`\[test\]`
 *
 * @param regexp - The string to escape / 要转义的字符串
 * @returns The escaped string / 转义后的字符串
 */
export declare const escapeRegExp: (regexp: string) => string;
/**
 * Scan the end line of a code fence block.
 *
 * 扫描代码围栏块的结束行。
 *
 * @param state - Block parser state / 块级解析器状态
 * @param startLine - Start line of the fence / 围栏开始行
 * @param endLine - Search boundary / 搜索边界
 * @param blkIndent - Block indent of the current scope / 当前作用域的块级缩进
 * @returns The line after the fence end, or `null` if the start line is not a fence /
 *   围栏结束后的下一行；若起始行不是围栏则返回 `null`
 */
export declare const scanFence: (state: StateBlock, startLine: number, endLine: number, blkIndent: number) => number | null;
/**
 * Matches any CommonMark line ending: `\n`, `\r\n`, or `\r`.
 *
 * 匹配任意 CommonMark 换行符：`\n`、`\r\n` 或 `\r`。
 */
export declare const NEWLINE_RE: RegExp;
/**
 * Matches a backslash escape of a CommonMark ASCII punctuation character.
 *
 * 匹配 CommonMark ASCII 标点字符的反斜杠转义。
 */
export declare const UNESCAPE_RE: RegExp;
/** Ruler type that can own a rule / 可持有规则的 ruler 类型 */
export type RuleScope = "block" | "core" | "inline";
/**
 * Check whether a parser rule is registered on a markdown-it instance.
 *
 * Markdown-it keeps separate core / block / inline rulers and does not enforce unique rule names
 * across them, so pass `scope` to avoid a false positive from another ruler. Within one ruler,
 * repeated registration of the same name is not deduplicated by markdown-it either.
 * `Ruler.getRules()` returns unnamed functions, hence this reads the ruler's internal `__rules__`
 * list.
 *
 * 检查 markdown-it 实例上是否已注册某个解析规则。
 *
 * Markdown-it 的 core / block / inline 是三个独立 ruler，不保证规则名跨 ruler 唯一， 因此可通过 `scope` 限定只检测某一个
 * ruler，避免其它 ruler 的同名规则造成误判。 同一 ruler 内重复注册同名规则 markdown-it 也不会去重。`Ruler.getRules()` 返回的函数不带名字，
 * 因此这里读取内部的 `__rules__`。
 *
 * @param md - Markdown-it instance / markdown-it 实例
 * @param ruleName - Rule name / 规则名
 * @param scope - Ruler to check; defaults to all three / 要检测的 ruler，默认检测三者
 * @returns Whether the rule is registered / 规则是否已注册
 */
export declare const hasRule: (md: MarkdownIt, ruleName: string, scope?: RuleScope) => boolean;
/**
 * Default patterns of files that must never be read.
 *
 * 默认禁止读取的文件模式。
 */
export declare const defaultSensitiveFiles: readonly string[];
/**
 * Check whether a POSIX-style path matches a sensitive file pattern.
 *
 * Patterns containing `/` match the whole path, while patterns without `/` match the basename.
 *
 * 检查 POSIX 风格路径是否命中敏感文件模式。
 *
 * 含 `/` 的模式匹配整个路径，不含 `/` 的模式匹配文件名（路径最后一段）。
 *
 * @example
 *   isSensitiveFile(".env"); // true
 *   isSensitiveFile("src/index.ts"); // false
 *
 * @param path - POSIX-style path / POSIX 风格路径
 * @param patterns - Glob or RegExp patterns / glob 或正则模式
 * @returns Whether the path is sensitive / 路径是否命中敏感文件
 */
export declare const isSensitiveFile: (path: string, patterns?: readonly (string | RegExp)[]) => boolean;
/**
 * Plugin without options.
 *
 * 无选项插件。
 *
 * @param md - MarkdownIt instance / MarkdownIt 实例
 */
type PluginSimple = (md: MarkdownIt) => void;
/**
 * Plugin with options.
 *
 * 带选项插件。
 *
 * @param md - MarkdownIt instance / MarkdownIt 实例
 * @param options - Plugin options / 插件选项
 */
type PluginWithOptions<T = unknown> = (md: MarkdownIt, options?: T) => void;
/**
 * Block rule.
 *
 * 块级规则。
 *
 * @param state - Block state / 块级状态
 * @param startLine - Start line / 开始行
 * @param endLine - End line / 结束行
 * @param silent - Whether the rule is in silent mode / 是否为静默模式
 * @returns Whether the rule is applied / 规则是否生效
 */
type BlockRule = (state: StateBlock, startLine: number, endLine: number, silent: boolean) => boolean;
/**
 * Core rule.
 *
 * 核心规则。
 *
 * @param state - Core state / 核心状态
 */
type CoreRule = (state: StateCore) => void;
/**
 * Inline rule.
 *
 * 行内规则。
 *
 * @param state - Inline state / 行内状态
 * @param silent - Whether the rule is in silent mode / 是否为静默模式
 * @returns Whether the rule is applied / 规则是否生效
 */
type InlineRule = (state: StateInline, silent: boolean) => boolean;
/**
 * Token nesting level.
 *
 * Token 嵌套级别。
 */
type Nesting = -1 | 0 | 1;
/**
 * Token metadata object.
 *
 * Token 元数据对象。
 */
type TokenMeta = Record<string | symbol, unknown>;
export type { BlockRule, CoreRule, InlineRule, Nesting, PluginSimple, PluginWithOptions, TokenMeta };